function createTrie() {
  const root = {}
  const walk = (s) => {
    let n = root
    for (const ch of s) {
      if (!n[ch]) return null
      n = n[ch]
    }
    return n
  }
  return {
    insert(word) {
      let n = root
      for (const ch of word) {
        if (!n[ch]) n[ch] = {}
        n = n[ch]
      }
      n.$ = true
    },
    search(word) {
      const n = walk(word)
      return n !== null && n.$ === true
    },
    startsWith(prefix) {
      return walk(prefix) !== null
    },
  }
}

