function createMinHeap() {
  const h = []
  const swap = (a, b) => {
    ;[h[a], h[b]] = [h[b], h[a]]
  }
  return {
    push(x) {
      h.push(x)
      let i = h.length - 1
      while (i > 0) {
        const p = Math.floor((i - 1) / 2)
        if (h[p] <= h[i]) break
        swap(p, i)
        i = p
      }
    },
    pop() {
      if (h.length === 0) return undefined
      const top = h[0]
      const last = h.pop()
      if (h.length > 0) {
        h[0] = last
        let i = 0
        while (true) {
          let s = i
          const l = 2 * i + 1
          const r = 2 * i + 2
          if (l < h.length && h[l] < h[s]) s = l
          if (r < h.length && h[r] < h[s]) s = r
          if (s === i) break
          swap(i, s)
          i = s
        }
      }
      return top
    },
    peek() {
      return h[0]
    },
    size() {
      return h.length
    },
  }
}

