function heapify(arr) {
  const n = arr.length
  const sink = (i) => {
    while (true) {
      let s = i
      const l = 2 * i + 1
      const r = 2 * i + 2
      if (l < n && arr[l] < arr[s]) s = l
      if (r < n && arr[r] < arr[s]) s = r
      if (s === i) return
      ;[arr[i], arr[s]] = [arr[s], arr[i]]
      i = s
    }
  }
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) sink(i)
  return arr
}

function topK(nums, k) {
  const h = []
  const swap = (a, b) => {
    ;[h[a], h[b]] = [h[b], h[a]]
  }
  const push = (x) => {
    h.push(x)
    let i = h.length - 1
    while (i > 0) {
      const p = Math.floor((i - 1) / 2)
      if (h[p] <= h[i]) break
      swap(p, i)
      i = p
    }
  }
  const pop = () => {
    const top = h[0]
    const last = h.pop()
    if (h.length > 0) {
      h[0] = last
      let i = 0
      while (true) {
        let s = i
        const l = 2 * i + 1
        const r = 2 * i + 2
        if (l < h.length && h[l] < h[s]) s = l
        if (r < h.length && h[r] < h[s]) s = r
        if (s === i) break
        swap(i, s)
        i = s
      }
    }
    return top
  }
  for (const x of nums) {
    push(x)
    if (h.length > k) pop()
  }
  const out = []
  while (h.length) out.push(pop())
  return out.reverse()
}
